--- a/crates/ruff_linter/src/rules/flake8_pie/rules/unnecessary_spread.rs
+++ b/crates/ruff_linter/src/rules/flake8_pie/rules/unnecessary_spread.rs
@@ -2,7 +2,7 @@ use ruff_diagnostics::{Diagnostic, Edit, Fix, FixAvailability, Violation};
 use ruff_macros::{derive_message_formats, ViolationMetadata};
 use ruff_python_ast::{self as ast, Expr};
 use ruff_python_trivia::{SimpleTokenKind, SimpleTokenizer};
-use ruff_text_size::{Ranged, TextSize};
+use ruff_text_size::{Ranged, TextRange, TextSize};

 use crate::checkers::ast::Checker;
 use crate::Locator;
@@ -74,32 +74,45 @@ fn unnecessary_spread_fix(
     let doublestar = SimpleTokenizer::starts_at(prev_end, locator.contents())
         .find(|tok| matches!(tok.kind(), SimpleTokenKind::DoubleStar))?;

-    if let Some(last) = dict.iter_values().last() {
-        // Ex) `**{a: 1, b: 2}`
-        let mut edits = vec![];
-        for tok in SimpleTokenizer::starts_at(last.end(), locator.contents()).skip_trivia() {
-            match tok.kind() {
-                SimpleTokenKind::Comma => {
-                    edits.push(Edit::range_deletion(tok.range()));
-                }
-                SimpleTokenKind::RBrace => {
-                    edits.push(Edit::range_deletion(tok.range()));
-                    break;
-                }
-                _ => {}
+    let mut edits = vec![];
+
+    // Delete the `**`, any wrapping parentheses, and the opening `{`.
+    for tok in SimpleTokenizer::new(
+        locator.contents(),
+        TextRange::new(doublestar.start(), dict.start() + TextSize::from(1)),
+    ) {
+        if matches!(
+            tok.kind(),
+            SimpleTokenKind::DoubleStar | SimpleTokenKind::LParen | SimpleTokenKind::LBrace
+        ) {
+            edits.push(Edit::range_deletion(tok.range()));
+        }
+    }
+
+    // Delete any trailing comma, the closing `}`, and any wrapping parentheses.
+    let trailing_start = dict
+        .iter_values()
+        .last()
+        .map_or(dict.start() + TextSize::from(1), Ranged::end);
+    let mut after_dict = false;
+    for tok in SimpleTokenizer::starts_at(trailing_start, locator.contents()) {
+        match tok.kind() {
+            SimpleTokenKind::Comma if !after_dict => {
+                edits.push(Edit::range_deletion(tok.range()));
+            }
+            SimpleTokenKind::RBrace if !after_dict => {
+                edits.push(Edit::range_deletion(tok.range()));
+                after_dict = true;
             }
+            SimpleTokenKind::RParen if after_dict => {
+                edits.push(Edit::range_deletion(tok.range()));
+            }
+            SimpleTokenKind::RParen => {}
+            kind if kind.is_trivia() => {}
+            _ => break,
         }
-        Some(Fix::safe_edits(
-            // Delete the first `**{`
-            Edit::deletion(doublestar.start(), dict.start() + TextSize::from(1)),
-            // Delete the trailing `}`
-            edits,
-        ))
-    } else {
-        // Ex) `**{}`
-        Some(Fix::safe_edit(Edit::deletion(
-            doublestar.start(),
-            dict.end(),
-        )))
     }
+
+    let first = edits.remove(0);
+    Some(Fix::safe_edits(first, edits))
 }
 M crates/ruff_linter/src/rules/flake8_pie/rules/unnecessary_spread.rs

